<template>
  <sravx-page-back root-only />

  <view class="page"><view class="gift"><view><text class="ui-small">Sravx Gift Card</text><text class="ui-strong">礼品卡兑换</text></view><text>GIFT</text><view><text class="ui-b">{{ preview }}</text><text class="ui-small">兑换后权益将自动发放至当前账号</text></view></view><view class="card"><text class="heading">输入兑换码</text><view class="input"><input :value="cardCode" maxlength="32" placeholder="请输入礼品卡兑换码" @input="input" @confirm="redeem"/><text v-if="cardCode" @tap="update('')">×</text></view><view class="quick"><button @tap="paste">粘贴</button><button @tap="scan">扫码</button></view><button class="redeem" :class="{ disabled: !canRedeem || redeeming }" @tap="redeem">{{ redeeming ? '兑换中...' : '立即兑换' }}</button></view><view v-if="result" class="card result" :class="result.type"><text class="heading">{{ result.title }}</text><text>{{ result.desc }}</text><view v-if="result.nextAction==='select_address'" class="address" @tap="address"><view v-if="selectedAddress"><text>{{ addressText }}</text><text class="ui-small">{{ selectedAddress.name }} {{ selectedAddress.phone }}</text></view><text v-else>请选择收货地址</text><text>›</text></view><button v-if="result.actionText" class="action" @tap="resultAction">{{ result.nextAction==='select_address' ? (selectedAddress ? '确认地址并生成订单' : '选择收货地址') : result.actionText }}</button></view><view class="card"><text class="heading">兑换说明</text><view v-for="(item,index) in rules" :key="item" class="rule"><text class="ui-b">{{ index + 1 }}</text><text>{{ item }}</text></view></view><view class="card"><view class="record-head"><text class="heading">最近记录</text><text class="ui-small" v-if="records.length">{{ records.length }} 条</text></view><view v-for="item in records" :key="item.id" class="record" @tap="recordAction(item)"><view><text>{{ item.title }}</text><text class="ui-small">{{ item.time }}</text></view><view><text class="ui-b">{{ item.value }}</text><text class="ui-small" v-if="item.nextAction==='select_address'">去处理</text></view></view><view v-if="!records.length" class="record-empty">暂无兑换记录</view></view><view class="contact">兑换遇到问题？<button open-type="contact" session-from="gift-card">联系客服</button></view></view>
</template>
<script>
import SravxPageBack from '../../components/sravx-page-back/sravx-page-back.vue'

import api from '../../common/api.js'
import auth from '../../common/auth.js'
const clean = value => String(value || '').toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,32)
const date = value => value ? String(value).replace('T',' ').slice(0,16).replace(/-/g,'.') : '--'
export default {components:{SravxPageBack}, data() { return { cardCode: '', canRedeem: false, redeeming: false, confirming: false, result: null, selectedAddress: null, records: [], rules: ['礼品卡仅可绑定至当前登录账号，兑换成功后不可转赠或撤销。','请确认兑换码完整无误，字母不区分大小写。','商品礼品需要收货地址；积分和优惠券会自动发放至当前账号。'] } }, computed: { preview() { return this.cardCode || 'XXXX-XXXX-XXXX' }, addressText() { const item = this.selectedAddress || {}; return `${item.province||''}${item.city||''}${item.district||''}${item.detail||''}` } }, onLoad() { if (this.requireLogin()) { this.loadAddress(); this.loadRecords() } }, onShow() { const item = uni.getStorageSync('sravx_gift_card_address'); if (item) { this.selectedAddress = item; uni.removeStorageSync('sravx_gift_card_address'); if (this.result && this.result.nextAction === 'select_address') this.confirmAddress() } }, methods: { requireLogin() { const user = auth.user(); if (user && user.phone) return true; uni.navigateTo({ url: '/pages/register/index' }); return false }, input(event) { this.update(event.detail.value) }, update(value) { this.cardCode = clean(value); this.canRedeem = this.cardCode.replace(/-/g,'').length >= 8; this.result = null }, paste() { uni.getClipboardData({ success: data => { const value = clean(data.data); value ? this.update(value) : uni.showToast({ title: '剪贴板没有兑换码', icon: 'none' }) } }) }, scan() { uni.scanCode({ onlyFromCamera: false, success: data => { const value = clean(data.result); value ? this.update(value) : uni.showToast({ title: '未识别到兑换码', icon: 'none' }) } }) }, async loadAddress() { try { const rows = api.asList(await api.getAddressList()); this.selectedAddress = rows.find(item => Number(item.is_default) === 1) || rows[0] || null } catch (error) {} }, async loadRecords() { try { const data = await api.getGiftCardRedeemRecords(1,5); const rows = api.asList(data); this.records = rows.map((item,index) => ({ id: item.id || `${item.code||'gift'}-${index}`, title: item.title || item.card_name || '礼品卡兑换', value: item.valueText || item.value_text || item.reward_text || item.amount_text || '已到账', time: date(item.redeemed_at || item.created_at || item.time), nextAction: item.nextAction || '', orderId: item.orderId || item.order_id || null })) } catch (error) { this.records = [] } }, async redeem() { if (this.redeeming || !this.requireLogin()) return; if (!this.canRedeem) return uni.showToast({ title: '请输入有效兑换码', icon: 'none' }); this.redeeming = true; try { const payload = { code: this.cardCode }; if (this.selectedAddress && this.selectedAddress.id) payload.addressId = this.selectedAddress.id; const data = await api.redeemGiftCard(payload); this.result = { type: 'success', recordId: data.recordId || null, orderId: data.orderId || null, nextAction: data.nextAction || '', actionText: data.actionText || '', title: data.title || '兑换成功', desc: data.benefitText || data.reward_text || data.name || '礼品卡权益已到账' }; this.update(''); uni.showToast({ title: '兑换成功', icon: 'success' }); this.loadRecords() } catch (error) { this.result = { type: 'error', title: '兑换未完成', desc: error.message && !error.message.includes('function') ? error.message : '礼品卡服务暂未开通，请联系客服处理。' } } finally { this.redeeming = false } }, address() { uni.navigateTo({ url: `/pages/address-manage/index?from=giftCard&selectedId=${this.selectedAddress && this.selectedAddress.id || ''}` }) }, async confirmAddress() { if (!this.result || !this.result.recordId) return uni.showToast({ title: '缺少兑换记录', icon: 'none' }); if (!this.selectedAddress || !this.selectedAddress.id) return this.address(); if (this.confirming) return; this.confirming = true; try { const data = await api.confirmGiftCardProductAddress({ recordId: this.result.recordId, addressId: this.selectedAddress.id }); this.result = { type: 'success', recordId: data.recordId || null, orderId: data.orderId || null, nextAction: data.nextAction || '', actionText: data.actionText || '', title: data.title || '订单已生成', desc: data.benefitText || data.reward_text || data.name || '礼品卡权益已到账' }; uni.showToast({ title: '订单已生成', icon: 'success' }); this.loadRecords() } catch (error) { uni.showToast({ title: error.message || '提交失败', icon: 'none' }) } finally { this.confirming = false } }, resultAction() { if (this.result.nextAction === 'select_address') return this.selectedAddress ? this.confirmAddress() : this.address(); if (this.result.nextAction === 'order_detail' && this.result.orderId) return uni.navigateTo({ url: `/pages/order-detail/index?id=${this.result.orderId}` }); if (this.result.nextAction === 'coupon_list') return uni.navigateTo({ url: '/pages/coupon-manage/index' }); if (this.result.nextAction === 'points_mall') uni.navigateTo({ url: '/pages/points-mall/index' }) }, recordAction(item) { if (item.nextAction === 'select_address') { this.result = { type: 'success', recordId: item.id, nextAction: 'select_address', actionText: '确认收货地址', title: '商品礼品待确认地址', desc: '请选择收货地址后生成礼品订单' } } else if (item.orderId) uni.navigateTo({ url: `/pages/order-detail/index?id=${item.orderId}` }) } } }
</script>
<style>
.page{min-height:100vh;padding:12px 16px 28px;box-sizing:border-box;background:#F4F6F8}.gift{display:flex;min-height:150px;padding:17px;box-sizing:border-box;flex-direction:column;justify-content:space-between;border-radius:12px;background:linear-gradient(135deg,#0B0D10,#2B3037 56%,#AEB7C3);color:#fff}.gift>view:first-child{display:flex;justify-content:space-between;flex-direction:column}.gift>div .ui-strong,.gift .ui-small{display:block}.gift>div .ui-strong{margin-top:5px;font-size:22px}.gift>div:last-child .ui-b{font-family:monospace;font-size:18px}.gift .ui-small{margin-top:5px;color:rgba(255,255,255,.7);font-size:11px}.gift>text{position:absolute;right:28px;top:28px;font-size:11px}.card{margin-top:12px;padding:15px;border-radius:10px;background:#fff;box-shadow:0 3px 10px rgba(29,29,31,.05)}.heading{display:block;font-size:15px;font-weight:650}.input{display:flex;align-items:center;height:48px;margin-top:12px;border:1px solid #e5e5ea;border-radius:8px}.input input{flex:1;padding:0 12px;font-family:monospace;font-size:14px}.input>text{width:36px;color:#c7c7cc;text-align:center;font-size:23px}.quick{display:flex;gap:8px;margin-top:9px}.quick button{flex:1;margin:0;background:#F4F6F8;font-size:12px;line-height:34px}.quick button::after,.redeem::after,.action::after{border:0}.redeem,.action{width:100%;margin-top:13px;border-radius:20px;background:#0B0D10;color:#fff;font-size:15px;line-height:42px}.redeem.disabled{opacity:.42}.result{border-left:4px solid #4A4A4D}.result.error{border-color:#4A4A4D}.result>text:nth-child(2){display:block;margin-top:5px;color:#636366;font-size:13px}.address{display:flex;align-items:center;justify-content:space-between;margin-top:10px;padding:10px;border-radius:7px;background:#F4F6F8;font-size:13px}.address .ui-small{display:block;margin-top:4px;color:#636366;font-size:11px}.rule{display:flex;gap:8px;margin-top:10px;color:#636366;font-size:12px;line-height:1.5}.rule .ui-b{display:flex;width:16px;height:16px;align-items:center;justify-content:center;flex-shrink:0;border-radius:50%;background:#F4F6F8;color:#0B0D10;font-size:10px}.record-head,.record{display:flex;align-items:center;justify-content:space-between}.record{padding:10px 0;border-bottom:1px solid #eee;font-size:13px}.record .ui-small{display:block;margin-top:3px;color:#636366;font-size:10px}.record>view:last-child{text-align:right;color:#0B0D10}.record-empty{padding:24px;text-align:center;color:#636366;font-size:12px}.contact{margin-top:12px;color:#636366;text-align:center;font-size:12px}.contact button{display:inline;margin:0;padding:0;background:transparent;color:#0B0D10;font-size:12px;line-height:normal}.contact button::after{border:0}
</style>
